import {serve} from '@hono/node-server';import {serveStatic} from '@hono/node-server/serve-static';import {Hono} from 'hono';import {z} from 'zod';import {calculate,type RequestInput} from './logic.js';
declare const process:{env:Record<string,string|undefined>};const maxBodyBytes=16_384;const schema=z.object({clearance_slug:z.string(),pressurized_pods:z.number().int(),vacuum_pods:z.number().int(),docking_arms:z.number().int(),solar_flare:z.boolean()}).strict();
const response=(value:unknown,status=200,headers:Record<string,string>={})=>{if(Object.keys(headers).some(name=>['content-length','content-type','connection','transfer-encoding','x-content-type-options'].includes(name.toLowerCase())))return new Response(JSON.stringify({error:'invalid_response_headers',detail:'server-owned response header'}),{status:500,headers:{'content-type':'application/json'}});return new Response(JSON.stringify(value),{status,headers:{'content-type':'application/json',...headers}})};const error=(code:string,status:number,detail:string)=>response({error:code,detail},status);const zero=(v:RequestInput,state:string)=>({clearance_slug:v.clearance_slug,payload_tally:0,transfer_effort:0,berth_allowance:0,approved_effort:0,spillover_effort:0,orbit_passes:0,clearance_rating:0,clearance_phase:state});const decide=(v:RequestInput,headers:Headers)=>{if((headers.get('x-orbit-credential')??'')!=="orbit-046")return response(zero(v,'authorization_required'),403,{"x-access-denial":"orbit_credential"});if([v.pressurized_pods,v.vacuum_pods,v.docking_arms].some(item=>item<0))return response(zero(v,'invalid'),422,{'x-validation':'nonnegative'});if(v.docking_arms===0&&v.pressurized_pods+v.vacuum_pods>0)return response(zero(v,'invalid'),422,{'x-validation':'docking_arms'});return response(calculate(v),200,{});};
const app=new Hono();app.get('/status/orbital-clearance-ready',()=>response({service:'Orbital Cargo Clearance',ready:true}));app.post('/api/v10/orbital-clearances',async context=>{const media=(context.req.header('content-type')??'').split(';',1)[0]!.trim().toLowerCase();if(media!=='application/json'&&!media.endsWith('+json'))return error('json_content_type_required',415,'expected application/json');const declared=context.req.header('content-length');if(declared&&(!/^\d+$/.test(declared)||Number(declared)>maxBodyBytes))return error('body_too_large',413,'request body exceeds 16384 bytes');const raw=await context.req.arrayBuffer();if(raw.byteLength>maxBodyBytes)return error('body_too_large',413,'request body exceeds 16384 bytes');try{const parsed=schema.safeParse(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw)));if(!parsed.success)return error('invalid_json',400,parsed.error.message);const result=decide(parsed.data,context.req.raw.headers);if(result.status!==200)return result;const calculated=calculate(parsed.data);return response(calculated,207,{location:`/api/v10/orbital-clearances/${calculated.clearance_slug}`,'x-clearance-phase':calculated.clearance_phase})}catch(caught){return error('invalid_json',400,String(caught))}});app.all('/api/*',context=>error('not_found',404,`no API route ${context.req.path}`));app.get('/parley.js',serveStatic({path:process.env.FULLSTACK_046_BROWSER??'./dist/logic.js'}));app.get('/*',serveStatic({root:'./public'}));serve({fetch:app.fetch,hostname:'127.0.0.1',port:Number(process.env.PARLEY_WEB_PORT)});
